const html =
  $json.html ||
  $json.textHtml ||
  $json.bodyHtml ||
  '';

// ======================================================
// FUNÇÃO PARA PEGAR HEADERS EM FORMATOS DIFERENTES
// ======================================================

function getHeader(nome) {
  const headers = $json.headers || {};

  const lower = nome.toLowerCase();
  const normal =
    nome.charAt(0).toUpperCase() +
    nome.slice(1).toLowerCase();

  const valor =
    headers[lower] ||
    headers[nome] ||
    headers[normal] ||
    $json[nome] ||
    $json[normal] ||
    '';

  return String(valor)
    .replace(new RegExp(`^${nome}:\\s*`, 'i'), '')
    .trim();
}

const subject = getHeader('subject');
const from = getHeader('from');

// ======================================================
// LIMPAR HTML
// ======================================================

const texto = html
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/gi, "'")
  .replace(/&ndash;/gi, '–')
  .replace(/&mdash;/gi, '—')
  .replace(/&#8211;/gi, '–')
  .replace(/&#8212;/gi, '—')
  .replace(/\s+/g, ' ')
  .trim();

// ======================================================
// IDENTIFICAR FONTE
// ======================================================

const origem = `${from} ${subject}`.toLowerCase();

let fonte = 'Outra';

if (
  origem.includes('indeed') ||
  html.toLowerCase().includes('indeed.com')
) {
  fonte = 'Indeed';
} else if (
  origem.includes('linkedin') ||
  html.toLowerCase().includes('linkedin.com')
) {
  fonte = 'LinkedIn';
} else if (
  origem.includes('gupy') ||
  html.toLowerCase().includes('gupy')
) {
  fonte = 'Gupy';
}

// ======================================================
// VALORES PADRÃO
// ======================================================

let cargo = 'Não informado';
let empresa = 'Não informado';
let localizacao = 'Não informado';
let modeloTrabalho = 'Não informado';
let tipoContrato = 'Não informado';
let salario = 'Não informado';
let descricao = 'Não informado';
let link = 'Não informado';

// ======================================================
// INDEED
// ======================================================

if (fonte === 'Indeed') {

  // ----------------------------------------------------
  // CARGO + EMPRESA PELO ASSUNTO
  //
  // Exemplos:
  // Analista QA Junior na empresa Konnex
  // Product Owner | SegImob na empresa Seg Imob...
  // ----------------------------------------------------

  const matchAssunto = subject.match(
    /^(.+?)\s+na empresa\s+(.+)$/i
  );

  if (matchAssunto) {
    cargo = matchAssunto[1].trim();
    empresa = matchAssunto[2].trim();
  }

  // ----------------------------------------------------
  // FALLBACK: tentar pelo conteúdo HTML
  // ----------------------------------------------------

  if (cargo === 'Não informado') {

    const h1 = html.match(
      /<h1[^>]*>(.*?)<\/h1>/i
    );

    if (h1) {
      const h1Limpo = h1[1]
        .replace(/<[^>]+>/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();

      const matchH1 = h1Limpo.match(
        /^(.+?)\s+na empresa\s+(.+)$/i
      );

      if (matchH1) {
        cargo = matchH1[1].trim();
        empresa = matchH1[2].trim();
      }
    }
  }

  // ----------------------------------------------------
  // MODELO DE TRABALHO
  // ----------------------------------------------------

  if (/\bremoto\b|\bremote\b/i.test(texto)) {
    modeloTrabalho = 'Remoto';
  } else if (
    /\bhíbrido\b|\bhibrido\b|\bhybrid\b/i.test(texto)
  ) {
    modeloTrabalho = 'Híbrido';
  } else if (
    /\bpresencial\b|\bon-site\b|\bonsite\b/i.test(texto)
  ) {
    modeloTrabalho = 'Presencial';
  }

  // ----------------------------------------------------
  // LOCALIZAÇÃO
  // ----------------------------------------------------

  // Se só conseguimos confirmar remoto
  if (modeloTrabalho === 'Remoto') {
    localizacao = 'Remoto';
  }

  // ----------------------------------------------------
  // TIPO DE VAGA
  // Procura especificamente a seção "Tipo de vaga"
  // ----------------------------------------------------

  const tipoMatch = texto.match(
    /Tipo de vaga\s+(.+?)(?:Pré-visualização|Descrição da vaga|Sobre a vaga|Salário|Saiba mais)/i
  );

  if (tipoMatch) {
    const tipoTexto = tipoMatch[1];

    if (/tempo integral/i.test(tipoTexto)) {
      tipoContrato = 'Tempo integral';
    } else if (/meio período|meio periodo/i.test(tipoTexto)) {
      tipoContrato = 'Meio período';
    } else if (/\bPJ\b/i.test(tipoTexto)) {
      tipoContrato = 'PJ';
    } else if (/contrato/i.test(tipoTexto)) {
      tipoContrato = 'Contrato';
    }
  } else {
    // fallback
    if (/tempo integral/i.test(texto)) {
      tipoContrato = 'Tempo integral';
    }
  }

  // ----------------------------------------------------
  // SALÁRIO DA VAGA
  //
  // Procuramos salário próximo da seção "Tipo de vaga"
  // para evitar pegar o salário mínimo do perfil.
  // ----------------------------------------------------

  const salarioMatch = texto.match(
    /Salário\s+(R\$\s*[\d.,]+(?:\s*[–-]\s*R\$\s*[\d.,]+)?\s*por\s+(?:mês|mes|hora|ano))\s+Tipo de vaga/i
  );

  if (salarioMatch) {
    salario = salarioMatch[1].trim();
  }

  // ----------------------------------------------------
  // DESCRIÇÃO
  // Aceita vários formatos de template do Indeed
  // ----------------------------------------------------

  const padroesDescricao = [
    /Pré-visualização da descrição da vaga\s+(.+?)(?:Saiba mais|Quer receber mais vagas|Mantenha seu perfil)/i,

    /Descrição da vaga\s+(.+?)(?:Saiba mais|Quer receber mais vagas|Mantenha seu perfil)/i,

    /Sobre a vaga\s+(.+?)(?:Saiba mais|Quer receber mais vagas|Mantenha seu perfil)/i
  ];

  for (const padrao of padroesDescricao) {
    const match = texto.match(padrao);

    if (match) {
      descricao = match[1]
        .replace(/\s+/g, ' ')
        .trim();

      break;
    }
  }

  // ----------------------------------------------------
  // LINK DA VAGA
  // ----------------------------------------------------

  const links = [
    ...html.matchAll(/href=["']([^"']+)["']/gi)
  ]
    .map(m =>
      m[1].replace(/&amp;/g, '&')
    )
    .filter(l =>
      l.startsWith('http')
    );

  const linksUnicos = [...new Set(links)];

  // Primeiro tenta encontrar CTA específico da vaga
  const linkCTA = html.match(
    /<a[^>]+href=["']([^"']+)["'][^>]*(?:aria-label=["'][^"']*job[^"']*["'])/i
  );

  if (linkCTA) {
    link = linkCTA[1].replace(/&amp;/g, '&');
  } else {
    const indeedLink = linksUnicos.find(l =>
      l.toLowerCase().includes('indeed.com')
    );

    if (indeedLink) {
      link = indeedLink;
    }
  }
}

// ======================================================
// LINKEDIN / GUPY
//
// Por enquanto preservamos o conteúdo para criarmos
// parsers específicos quando testarmos e-mails reais.
// ======================================================

if (
  fonte === 'LinkedIn' ||
  fonte === 'Gupy'
) {

  // tenta cargo + empresa pelo assunto quando possível
  const padroes = [
    /^(.+?)\s+na empresa\s+(.+)$/i,
    /^(.+?)\s+at\s+(.+)$/i
  ];

  for (const padrao of padroes) {
    const match = subject.match(padrao);

    if (match) {
      cargo = match[1].trim();
      empresa = match[2].trim();
      break;
    }
  }

  if (/\bremoto\b|\bremote\b/i.test(texto)) {
    modeloTrabalho = 'Remoto';
    localizacao = 'Remoto';
  } else if (
    /\bhíbrido\b|\bhibrido\b|\bhybrid\b/i.test(texto)
  ) {
    modeloTrabalho = 'Híbrido';
  } else if (
    /\bpresencial\b|\bon-site\b|\bonsite\b/i.test(texto)
  ) {
    modeloTrabalho = 'Presencial';
  }

  const links = [
    ...html.matchAll(/href=["']([^"']+)["']/gi)
  ]
    .map(m =>
      m[1].replace(/&amp;/g, '&')
    )
    .filter(l =>
      l.startsWith('http')
    );

  const dominio =
    fonte === 'LinkedIn'
      ? 'linkedin'
      : 'gupy';

  const encontrado = links.find(l =>
    l.toLowerCase().includes(dominio)
  );

  if (encontrado) {
    link = encontrado;
  }
}

// ======================================================
// SAÍDA
// ======================================================

return {
  json: {
    id_email: $json.id,

    fonte,

    cargo,
    empresa,

    localizacao,
    modelo_trabalho: modeloTrabalho,
    tipo_contrato: tipoContrato,

    salario,

    // padronizado SEM ACENTO
    descricao,

    link,

    assunto_email: subject,
    remetente: from,

    // útil como fallback no WF02
    texto_email: texto,

    status: 'NOVA'
  }
};
